#ifndef BOTANIK_FW_FIRMWARE_H
#define BOTANIK_FW_FIRMWARE_H

/**
 * @file firmware.h
 * @brief OPTA firmware: site payload + the library wiring driven by run().
 *
 * Hardware counterpart of botanik_sim/main.cpp. The simulator allocates the PLC
 * shared memory locally and animates it from a worker thread; on the OPTA the
 * memory is owned by the M4 coprocessor and reached through HAL::get_plc_input()/
 * HAL::get_plc_output(), so this file only binds to it.
 *
 * The PlcInputData_t / PlcOutputData_t below are PLACEHOLDERS. The real layout is
 * generated by the PLC IDE and shared byte-for-byte with the coprocessor; until
 * that lands these stubs let the firmware link and the pages render. Replace them
 * with the generated types and verify with the static_asserts noted in
 * botanik_sim/simulator.h.
 */

#include "libbotanik.h"
#include "libbotanik/utils/text.h"   // format_float - snprintf has no %f on Mbed

#include <cstdint>
#include <cstdio>   // snprintf - page rendering

namespace Botanik { namespace Firmware {

// PLC shared-memory payload (placeholder)
// ----------------------------------------------------------------------------

/** @brief Inbound payload (PLC <- OPTA). Library log fields only, for now. */
struct PlcInputData_t {};

/** @brief Outbound payload (PLC -> OPTA). Minimal stub: enough to render the
 *  home page. Ordered widest-first and padded to a 4-byte multiple so the
 *  combined PlcOutput<> layout has no implicit gaps (see plcio/vars.h). */
struct PlcOutputData_t {
    int16_t  ext_temp_c_centi;   ///< exterior air temp, 0.01 degC
    uint16_t ext_rh_centi_pct;   ///< exterior relative humidity, 0.01 %
};
static_assert(sizeof(PlcOutputData_t) % 4 == 0, "PlcOutputData_t must be 4-byte aligned");

// Site pages (placeholder)
// ----------------------------------------------------------------------------

/** @brief Home page: a compact key-readings summary. */
class HomePage : public Pages::HomePage<PlcOutputData_t> {
public:
    HomePage(Terminal::AnsiTerminal& terminal, const PlcOutputData_t* data)
        : Pages::HomePage<PlcOutputData_t>(terminal, data) {}

protected:
    void draw_payload_static() override {
        _label(11, "Temp");
        _label(12, "Humidity");
    }

    void draw_payload_dynamic() override {
        const PlcOutputData_t* d = data();
        if (d == nullptr) return;
        char buf[32], f[12];
        snprintf(buf, sizeof(buf), "%s C",
                 Utils::format_float(f, sizeof(f), d->ext_temp_c_centi / 100.0, 1, 4));
        _value(11, buf);
        snprintf(buf, sizeof(buf), "%s%%",
                 Utils::format_float(f, sizeof(f), d->ext_rh_centi_pct / 100.0, 1, 4));
        _value(12, buf);
    }
};

// Firmware aggregate
// ----------------------------------------------------------------------------

/**
 * @brief Owns every long-lived library object and the main-loop step.
 *
 * Members are declared in dependency order so the constructor's initializer list
 * can hand each one the contexts/pointers built before it (scheduler publishes the
 * loop timestamp the PLC layer and terminal read; the PLC handler exposes the
 * output buffer the home page renders). A single instance lives in a function-local
 * static in main() - see botanik_fw/main.cpp - constructed once the Arduino core
 * has run its own init().
 */
class BotanikFirmware {
public:
    BotanikFirmware();

    /** @brief Drive step() forever; never returns. The firmware's main loop. */
    void run();

    /** @brief One main-loop iteration. */
    void step();

private:
    Utils::BufferedSerial  _console_serial;
    Utils::BufferedSerial  _monitor_serial;
    Logs::Logger           _logger;
    Logs::MonitorLogWriter _monitor;
    Scheduler::LoopScheduler _scheduler;

    // PLC shared memory lives in the coprocessor's region; we only bind to it.
    PlcIO::PlcInput<PlcInputData_t>*   _shared_in;
    PlcIO::PlcOutput<PlcOutputData_t>* _shared_out;

    PlcIO::PlcSyncHandler<PlcInputData_t, PlcOutputData_t> _plc_handler;
    PlcIO::PlcLogReader    _plc_log_reader;

    SystemContext          _sys_ctx;
    Terminal::AnsiTerminal _terminal;

    Pages::ShellPage _shell_page;
    Pages::LogsPage  _logs_page;
    HomePage         _home_page;
};

}}  // namespace Botanik::Firmware

#endif // BOTANIK_FW_FIRMWARE_H
